147 :   protected List<PassFactory> getChecks() {
148 :     List<PassFactory> checks = Lists.newArrayList();
149 : 
150 :     if (options.nameAnonymousFunctionsOnly) {
151 :       if (options.anonymousFunctionNaming ==
152 :           AnonymousFunctionNamingPolicy.MAPPED) {
153 :         checks.add(nameMappedAnonymousFunctions);
154 :       } else if (options.anonymousFunctionNaming ==
155 :           AnonymousFunctionNamingPolicy.UNMAPPED) {
156 :         checks.add(nameUnmappedAnonymousFunctions);
157 :       }
158 :       return checks;
159 :     }
160 : 
161 :     if (options.checkSuspiciousCode) {
162 :       checks.add(suspiciousCode);
163 :     }
164 : 
165 :     if (options.checkControlStructures)  {
166 :       checks.add(checkControlStructures);
167 :     }
168 : 
169 :     if (options.checkRequires.isOn()) {
170 :       checks.add(checkRequires);
171 :     }
172 : 
173 :     if (options.checkProvides.isOn()) {
174 :       checks.add(checkProvides);
175 :     }
176 : 
177 :     // The following passes are more like "preprocessor" passes.
178 :     // It's important that they run before most checking passes.
179 :     // Perhaps this method should be renamed?
180 :     if (options.generateExports) {
181 :       checks.add(generateExports);
182 :     }
183 : 
184 :     if (options.exportTestFunctions) {
185 :       checks.add(exportTestFunctions);
186 :     }
187 : 
188 :     if (options.closurePass) {
189 :       checks.add(closurePrimitives.makeOneTimePass());
190 :     }
191 : 
192 :     if (options.closurePass && options.checkMissingGetCssNameLevel.isOn()) {
193 :       checks.add(closureCheckGetCssName);
194 :     }
195 : 
196 :     if (options.closurePass) {
197 :       checks.add(closureReplaceGetCssName);
198 :     }
199 : 
200 :     if (options.syntheticBlockStartMarker != null) {
201 :       // This pass must run before the first fold constants pass.
202 :       checks.add(createSyntheticBlocks);
203 :     }
204 : 
205 :     // All passes must run the variable check. This synthesizes
206 :     // variables later so that the compiler doesn't crash. It also
207 :     // checks the externs file for validity. If you don't want to warn
208 :     // about missing variable declarations, we shut that specific
209 :     // error off.
210 :     WarningsGuard warningsGuard = options.getWarningsGuard();
211 :     if (!options.checkSymbols &&
212 :         (warningsGuard == null || !warningsGuard.disables(
213 :             DiagnosticGroups.CHECK_VARIABLES))) {
214 :       options.setWarningLevel(DiagnosticGroups.CHECK_VARIABLES,
215 :           CheckLevel.OFF);
216 :     }
217 : 
218 :     checks.add(checkVars);
219 : 
220 :     if (options.checkShadowVars.isOn()) {
221 :       checks.add(checkShadowVars);
222 :     }
223 : 
224 :     if (options.aggressiveVarCheck.isOn()) {
225 :       checks.add(checkVariableReferences);
226 :     }
227 : 
228 :     // This pass should run before types are assigned.
229 :     if (options.processObjectPropertyString) {
230 :       checks.add(objectPropertyStringPreprocess);
231 :     }
232 : 
233 :     // DiagnosticGroups override the plain checkTypes option.
234 :     if (options.enables(DiagnosticGroups.CHECK_TYPES)) {
235 :       options.checkTypes = true;
236 :     } else if (options.disables(DiagnosticGroups.CHECK_TYPES)) {
237 :       options.checkTypes = false;
238 :     }
239 : 
240 :     // Type-checking already does more accurate method arity checking, so don't
241 :     // do legacy method arity checking unless checkTypes is OFF.
242 :     if (options.checkTypes) {
243 :       checks.add(resolveTypes.makeOneTimePass());
244 :       checks.add(inferTypes.makeOneTimePass());
245 :       checks.add(checkTypes.makeOneTimePass());
246 :     } else {
247 :       if (options.checkFunctions.isOn()) {
248 :         checks.add(checkFunctions);
249 :       }
250 : 
251 :       if (options.checkMethods.isOn()) {
252 :         checks.add(checkMethods);
253 :       }
254 :     }
255 : 
256 :     if (options.checkUnreachableCode.isOn() ||
257 :         (options.checkTypes && options.checkMissingReturn.isOn())) {
258 :       checks.add(checkControlFlow);
259 :     }
260 : 
261 :     // CheckAccessControls only works if check types is on.
262 :     if (options.enables(DiagnosticGroups.ACCESS_CONTROLS)
263 :         && options.checkTypes) {
264 :       checks.add(checkAccessControls);
265 :     }
266 : 
267 :     if (options.checkGlobalNamesLevel.isOn()) {
268 :       checks.add(checkGlobalNames);
269 :     }
270 : 
271 :     if (options.checkUndefinedProperties.isOn() ||
272 :         options.checkUnusedPropertiesEarly) {
273 :       checks.add(checkSuspiciousProperties);
274 :     }
275 : 
276 :     if (options.checkCaja || options.checkEs5Strict) {
277 :       checks.add(checkStrictMode);
278 :     }
279 : 
280 :     // Defines in code always need to be processed.
281 :     checks.add(processDefines);
282 : 
283 :     if (options.instrumentationTemplate != null ||
284 :         options.recordFunctionInformation) {
285 :       checks.add(computeFunctionNames);
286 :     }
287 : 
288 :     assertAllOneTimePasses(checks);
289 :     return checks;
290 :   }"

